from __future__ import annotations
import base64, shutil, sys
from datetime import datetime
from pathlib import Path

ROOT=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path.cwd().resolve()
STAMP=datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP=ROOT/f"backup_arvores_recolhiveis_{STAMP}"
CONTENTS={
    ROOT/"app/static/classic-tree.js": base64.b64decode(""),
    ROOT/"app/static/comparison.js": base64.b64decode(""),
    ROOT/"app/templates/portal_profile.html": base64.b64decode(""),
}
CSS_PATH=ROOT/"app/static/styles.css"
CSS_BLOCK='\n/* ARVORES_RECOLHIVEIS_V1 */\n.tree-panel-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}\n.tree-panel-heading h2{margin:0}\n.tree-expand-controls{display:inline-flex;align-items:center;gap:7px;margin-left:auto}\n.tree-expand-controls button{padding:7px 10px;font-size:13px;white-space:nowrap}\n.static-access-tree{margin-top:12px}\n.static-access-tree details{border:1px solid #dbe4ec;border-radius:8px;background:#fbfcfe;margin:6px 0;overflow:hidden}\n.static-access-tree details>summary{cursor:pointer;padding:9px 11px;color:#17365d}\n.static-access-tree details>div,.static-access-tree details>ul{margin:0;padding:4px 12px 10px 26px}\n@media(max-width:700px){.tree-expand-controls{width:100%;margin-left:0}.tree-expand-controls button{flex:1}}\n'
required=[*CONTENTS,CSS_PATH]
missing=[str(path) for path in required if not path.exists()]
if missing: raise RuntimeError("Arquivos nao encontrados: "+", ".join(missing))

# Protecoes estruturais para nao aplicar sobre uma versao inesperada.
checks={
    ROOT/"app/static/classic-tree.js": "ClassicAccessTree",
    ROOT/"app/static/comparison.js": "comparison-data",
    ROOT/"app/templates/portal_profile.html": "Árvore de acessos",
    CSS_PATH: ".classic-tree",
}
for path,marker in checks.items():
    if marker not in path.read_text(encoding="utf-8-sig"):
        raise RuntimeError(f"Estrutura nao reconhecida em {path}. Nenhum arquivo foi alterado.")

for path in required:
    dest=BACKUP/path.relative_to(ROOT)
    dest.parent.mkdir(parents=True,exist_ok=True)
    shutil.copy2(path,dest)

try:
    for path,content in CONTENTS.items(): path.write_bytes(content)
    current_css=CSS_PATH.read_text(encoding="utf-8-sig")
    if "ARVORES_RECOLHIVEIS_V1" not in current_css:
        CSS_PATH.write_text(current_css.rstrip()+"\n"+CSS_BLOCK,encoding="utf-8")
    # Verificacoes finais objetivas.
    if "details.open=false" not in (ROOT/"app/static/classic-tree.js").read_text(encoding="utf-8"):
        raise RuntimeError("A arvore classica nao foi configurada como recolhida.")
    if "details.open=false" not in (ROOT/"app/static/comparison.js").read_text(encoding="utf-8"):
        raise RuntimeError("A arvore de comparacao nao foi configurada como recolhida.")
    if "data-static-access-tree" not in (ROOT/"app/templates/portal_profile.html").read_text(encoding="utf-8"):
        raise RuntimeError("A arvore do perfil nao recebeu os controles.")
except Exception:
    for path in required:
        saved=BACKUP/path.relative_to(ROOT)
        if saved.exists(): shutil.copy2(saved,path)
    raise

print("\n[SUCESSO] Arvores recolhiveis instaladas.")
print("[OK] Arvores iniciam fechadas.")
print("[OK] Expansao individual preservada.")
print("[OK] Botoes Expandir tudo e Recolher tudo adicionados.")
print("[OK] Comparacao, consolidado, perfis do usuario e perfil individual tratados.")
print(f"[BACKUP] {BACKUP}")
print("\nReinicie o servidor e atualize o navegador com Ctrl+F5.")
